contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 dep, uint256 wd) public payable {
        require(address(this).balance >= dep + wd);
        require(dep <= 1e18);
        require(wd <= 1e18);

        c.fallback{value: dep}();

        uint256 balBefore = c.balances(address(this));
        uint256 cBefore = address(c).balance;

        bool withdrew;
        try c.withdraw() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        uint256 balAfter = c.balances(address(this));

        if (withdrew) {
            assert(balAfter == 0);
            assert(cBefore == balBefore);
        } else {
            assert(balAfter == balBefore);
        }
    }

    receive() external payable {}

    fallback() external payable {}
}

