        uint256 afterBalance = c.balances(msg.sender);
        uint256 cBalanceAfter = address(c).balance;

        assert(
            (reverted && afterBalance == beforeBalance && cBalanceAfter <= cBalanceBefore) ||
            (!reverted && afterBalance == 0 && cBalanceBefore >= cBalanceAfter && cBalanceBefore - cBalanceAfter >= beforeBalance - afterBalance && cBalanceBefore - cBalanceAfter <= beforeBalance && lockReleased)
